#!/usr/bin/env elixir
# GENERATED by the foreman-jobsite-template skill -- one agent, looping until it
# emits the completion signal (bounded by max_iterations).
#
# Same run requirements as basic.exs: plain `elixir`, OTP 27+, FOREMAN_API_TOKEN.
#
#   export FOREMAN_API_TOKEN=...
#   export FOREMAN_PROJECT_ID=...
#   elixir this-script.exs

Mix.install([{:foreman_client, github: "ldangelo/foreman", sparse: "packages/foreman_client"}])

project_id = System.get_env("FOREMAN_PROJECT_ID") || "REPLACE-WITH-A-REGISTERED-PROJECT-ID"
# Parsed, not floored: the server's `optional_pos_int` refuses `0` outright
# (spec_option_invalid), and `String.to_integer/1` crashes on malformed input with no
# clear message. Require a positive integer; reject anything else with a named error.
raw_max = System.get_env("FOREMAN_MAX_ITERATIONS", "20")
max_iterations =
  case Integer.parse(raw_max) do
    {n, rest} when n >= 1 and rest in ["", "\n"] -> n
    _ -> raise "FOREMAN_MAX_ITERATIONS must be a positive integer, got: #{inspect(raw_max)}"
  end

# agent.env is refused unless EVERY key is allowlisted on the server via
# FOREMAN_JOBSITES_AGENT_ENV_ALLOWLIST. Names are listed here, values are read
# from THIS shell. They are never persisted on JobsiteStarted, so a resumed
# jobsite runs without them.
env =
  "FOREMAN_AGENT_ENV"
  |> System.get_env("")
  |> String.split(",", trim: true)
  |> Enum.map(fn name -> {name, System.get_env(name)} end)
  |> Enum.reject(fn {_k, v} -> is_nil(v) end)
  |> Map.new()

agent =
  %{"provider" => "pi", "model" => "REPLACE-WITH-A-MODEL",
    "approval_mode" => "auto_approve"}
  |> then(fn a -> if env == %{}, do: a, else: Map.put(a, "env", env) end)

spec = %{
  "project_id" => project_id,
  "name" => "my-loop",
  "prompt" => """
  Replace with the multi-turn instructions, and state the exact end signal, e.g.
  "when every test passes, print <promise>COMPLETE</promise> on its own line".
  """,
  "strategy" => %{"branch" => "agent/my-loop"},
  "sandbox" => "docker",
  "max_iterations" => max_iterations,
  "completion_signal" => "<promise>COMPLETE</promise>",
  "agent" => agent
}

client = Foreman.Client.new()

case Foreman.Client.run(client, spec) do
  {:ok, jobsite} ->
    # The read model's iteration fields are `iterations` (a list of per-iteration
    # records) and `iteration_index` (the 0-based index of the current/last one) --
    # `projection_store.ex:1973,1994` and the `%{jobsite_id: ...}` initial projection at
    # `:2493`, serialized by `JobsiteController.json_safe/1`. There is no
    # `iteration_count` and no `iteration_results`; asking for one yields nil and prints
    # "iterations=nil" as if the loop never ran. len(iterations) is the number of turns
    # actually taken, which is the number to compare against max_iterations.
    iters = jobsite["iterations"] || []
    IO.puts("status=#{jobsite["status"]} turns=#{length(iters)}/#{spec["max_iterations"]} last_index=#{inspect(jobsite["iteration_index"])}")
    IO.puts("branch=#{jobsite["branch"]}")

  {:error, {:jobsite, %{"status" => "failed"} = jobsite}} ->
    # max_iterations exhausted without the signal: the work is real, the loop
    # just did not converge. Inspect, then re-run with a higher bound or a
    # sharpened prompt rather than accepting this as "done".
    IO.puts(:stderr, "loop ended without the completion signal: #{inspect(Map.get(jobsite, "last_error") || Map.get(jobsite, "error"))}")
    IO.puts(:stderr, "branch=#{inspect(jobsite["branch"])} turns=#{length(jobsite["iterations"] || [])}/#{spec["max_iterations"]}")
    System.halt(1)

  {:error, {:transport, reason}} ->
    # Ordered BEFORE the 2-tuple arm: a transport error is itself a 2-tuple, so the
    # looser clause would swallow it and `:json.encode/1` would be handed an atom.
    IO.puts(:stderr, "cannot reach the server: #{inspect(reason)}")
    System.halt(1)

  {:error, other} ->
    IO.puts(:stderr, "jobsite did not complete: #{inspect(other)}")
    System.halt(1)
end
